  <meta property="og:image" content="https://snapframe.com/og-image.jpg">
  <meta property="twitter:card" content="summary_large_image">
  <meta property="twitter:url" content="https://snapframe.com/about">
  <meta property="twitter:title" content="SnapFrame — Capture, Create & Share What You Love">
  <meta property="twitter:description" content="SnapFrame is a social media platform that makes it easy to capture, create, and share what you love with the people who matter most.">
  <meta property="twitter:image" content="https://snapframe.com/og-image.jpg">
  <link rel="icon" type="image/svg+xml" href="favicon.svg">
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet">
  <style>
    *, *::before, *::after {
      box-sizing: border-box;
      margin: 0;
      padding: 0;
    }

    :root {
      --black: #000000;
      --purple: #7638FA;
      --purple-light: #9B6BFF;
      --orange: #FF7A00;
      --orange-light: #FF9A3D;
      --magenta: #FF3B8D;
      --white: #FFFFFF;
      --gray-50: #F9FAFB;
      --gray-100: #F3F4F6;
      --gray-200: #E5E7EB;
      --gray-300: #D1D5DB;
      --gray-400: #9CA3AF;
      --gray-500: #6B7280;
      --gray-600: #4B5563;
      --gray-700: #374151;
      --gray-800: #1F2937;
      --gray-900: #111827;
      --gradient-primary: linear-gradient(135deg, var(--purple) 0%, var(--magenta) 50%, var(--orange) 100%);
      --gradient-subtle: linear-gradient(135deg, rgba(118, 56, 250, 0.08) 0%, rgba(255, 59, 141, 0.08) 50%, rgba(255, 122, 0, 0.08) 100%);
      --shadow-sm: 0 1px 2px rgba(0, 0, 0, 0.05);
      --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
      --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05);
      --shadow-xl: 0 20px 25px -5px rgba(0, 0, 0, 0.1), 0 10px 10px -5px rgba(0, 0, 0, 0.04);
      --radius-sm: 8px;
      --radius-md: 12px;
      --radius-lg: 16px;
      --radius-xl: 24px;
      --radius-full: 9999px;
    }

    html {
      scroll-behavior: smooth;
    }

    body {
      font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
      background-color: var(--white);
      color: var(--gray-900);
      line-height: 1.6;
      -webkit-font-smoothing: antialiased;
      -moz-osx-font-smoothing: grayscale;
    }

    a {
      color: inherit;
      text-decoration: none;
    }

    img {
      max-width: 100%;
      display: block;
    }

    /* Header */
    .header {
      position: fixed;
      top: 0;
      left: 0;
      right: 0;
      z-index: 1000;
      background: rgba(255, 255, 255, 0.95);
      backdrop-filter: blur(10px);
      -webkit-backdrop-filter: blur(10px);
      border-bottom: 1px solid var(--gray-100);
    }

    .header-inner {
      max-width: 1200px;
      margin: 0 auto;
      padding: 0 24px;
      height: 64px;
      display: flex;
      align-items: center;
      justify-content: space-between;
    }

    .logo {
      font-size: 24px;
      font-weight: 800;
      background: var(--gradient-primary);
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      background-clip: text;
      letter-spacing: -0.5px;
    }

    .nav-desktop {
      display: none;
    }

    @media (min-width: 768px) {
      .nav-desktop {
        display: flex;
        align-items: center;
        gap: 32px;
      }
    }

    .nav-desktop a {
      font-size: 14px;
      font-weight: 500;
      color: var(--gray-600);
      transition: color 0.2s;
    }

    .nav-desktop a:hover {
      color: var(--gray-900);
    }

    .btn-login {
      background: var(--black);
      color: var(--white) !important;
      padding: 10px 20px;
      border-radius: var(--radius-full);
      font-weight: 600 !important;
      transition: transform 0.2s, box-shadow 0.2s;
    }

    .btn-login:hover {
      transform: translateY(-1px);
      box-shadow: var(--shadow-md);
    }

    .hamburger {
      display: flex;
      flex-direction: column;
      gap: 5px;
      background: none;
      border: none;
      cursor: pointer;
      padding: 8px;
      margin-right: -8px;
    }

    .hamburger span {
      width: 24px;
      height: 2px;
      background: var(--gray-900);
      border-radius: 2px;
      transition: transform 0.3s, opacity 0.3s;
    }

    .hamburger.active span:nth-child(1) {
      transform: translateY(7px) rotate(45deg);
    }

    .hamburger.active span:nth-child(2) {
      opacity: 0;
    }

    .hamburger.active span:nth-child(3) {
      transform: translateY(-7px) rotate(-45deg);
    }

    @media (min-width: 768px) {
      .hamburger {
        display: none;
      }
    }

    /* Mobile Menu */
    .mobile-menu {
      position: fixed;
      top: 64px;
      left: 0;
      right: 0;
      bottom: 0;
      background: var(--white);
      z-index: 999;
      padding: 24px;
      display: flex;
      flex-direction: column;
      gap: 8px;
      transform: translateX(100%);
      transition: transform 0.3s ease;
      overflow-y: auto;
    }

    .mobile-menu.active {
      transform: translateX(0);
    }

    .mobile-menu a {
      display: block;
      padding: 16px 0;
      font-size: 18px;
      font-weight: 600;
      color: var(--gray-800);
      border-bottom: 1px solid var(--gray-100);
    }

    .mobile-menu .btn-login {
      margin-top: 16px;
      text-align: center;
    }

    @media (min-width: 768px) {
      .mobile-menu {
        display: none;
      }
    }

    /* Hero */
    .hero {
      padding: 140px 24px 80px;
      background: var(--gradient-subtle);
      position: relative;
      overflow: hidden;
    }

    .hero::before {
      content: '';
      position: absolute;
      top: -50%;
      right: -20%;
      width: 600px;
      height: 600px;
      background: radial-gradient(circle, rgba(118, 56, 250, 0.15) 0%, transparent 70%);
      pointer-events: none;
    }

    .hero::after {
      content: '';
      position: absolute;
      bottom: -30%;
      left: -10%;
      width: 500px;
      height: 500px;
      background: radial-gradient(circle, rgba(255, 123, 0, 0.1) 0%, transparent 70%);
      pointer-events: none;
    }

    .hero-inner {
      max-width: 800px;
      margin: 0 auto;
      text-align: center;
      position: relative;
      z-index: 1;
    }

    .hero h1 {
      font-size: clamp(32px, 6vw, 56px);
      font-weight: 800;
      line-height: 1.1;
      letter-spacing: -1px;
      margin-bottom: 24px;
      color: var(--gray-900);
    }

    .hero h1 span {
      background: var(--gradient-primary);
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      background-clip: text;
    }

    .hero p {
      font-size: 18px;
      color: var(--gray-600);
      max-width: 560px;
      margin: 0 auto 40px;
      line-height: 1.7;
    }

    .btn-primary {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      background: var(--gradient-primary);
      color: var(--white);
      padding: 16px 32px;
      border-radius: var(--radius-full);
      font-size: 16px;
      font-weight: 700;
      border: none;
      cursor: pointer;
      transition: transform 0.2s, box-shadow 0.2s;
      box-shadow: 0 4px 14px rgba(118, 56, 250, 0.35);
    }

    .btn-primary:hover {
      transform: translateY(-2px);
      box-shadow: 0 6px 20px rgba(118, 56, 250, 0.45);
    }

    /* Section base */
    .section {
      padding: 80px 24px;
    }

    .section-inner {
      max-width: 1200px;
      margin: 0 auto;
    }

    .section-label {
      display: inline-block;
      font-size: 12px;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 1px;
      color: var(--purple);
      margin-bottom: 12px;
    }

    .section-heading {
      font-size: clamp(28px, 4vw, 40px);
      font-weight: 800;
      line-height: 1.2;
      letter-spacing: -0.5px;
      margin-bottom: 16px;
      color: var(--gray-900);
    }

    .section-heading a {
      color: var(--purple);
      transition: color 0.2s;
    }

    .section-heading a:hover {
      color: var(--purple-light);
    }

    .section-description {
      font-size: 17px;
      color: var(--gray-600);
      max-width: 600px;
      line-height: 1.7;
    }

    /* Features */
    .features {
      background: var(--white);
    }

    .features-grid {
      display: grid;
      grid-template-columns: 1fr;
      gap: 24px;
      margin-top: 48px;
    }

    @media (min-width: 768px) {
      .features-grid {
        grid-template-columns: repeat(2, 1fr);
      }
    }

    @media (min-width: 1024px) {
      .features-grid {
        grid-template-columns: repeat(4, 1fr);
      }
    }

    .feature-card {
      padding: 32px 24px;
      background: var(--gray-50);
      border-radius: var(--radius-lg);
      text-align: center;
      transition: transform 0.2s, box-shadow 0.2s;
    }

    .feature-card:hover {
      transform: translateY(-4px);
      box-shadow: var(--shadow-lg);
    }

    .feature-icon {
      width: 56px;
      height: 56px;
      margin: 0 auto 20px;
      background: var(--gradient-primary);
      border-radius: var(--radius-md);
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .feature-icon svg {
      width: 28px;
      height: 28px;
      color: var(--white);
    }

    .feature-card h3 {
      font-size: 18px;
      font-weight: 700;
      margin-bottom: 8px;
      color: var(--gray-900);
    }

    .feature-card p {
      font-size: 14px;
      color: var(--gray-500);
      line-height: 1.6;
    }

    /* Safety */
    .safety {
      background: linear-gradient(180deg, rgba(118, 56, 250, 0.04) 0%, rgba(255, 59, 141, 0.04) 100%);
    }

    .safety-content {
      display: grid;
      grid-template-columns: 1fr;
      gap: 48px;
      align-items: center;
      margin-top: 48px;
    }

    @media (min-width: 768px) {
      .safety-content {
        grid-template-columns: 1fr 1fr;
      }
    }

    .safety-visual {
      background: linear-gradient(135deg, var(--purple) 0%, var(--magenta) 100%);
      border-radius: var(--radius-xl);
      padding: 48px;
      display: flex;
      align-items: center;
      justify-content: center;
      min-height: 300px;
    }

    .safety-visual svg {
      width: 120px;
      height: 120px;
      color: var(--white);
      opacity: 0.9;
    }

    .safety-text .section-heading {
      color: var(--gray-900);
    }

    .safety-text .section-description {
      margin-bottom: 24px;
    }

    .safety-list {
      list-style: none;
      display: flex;
      flex-direction: column;
      gap: 12px;
    }

    .safety-list li {
      display: flex;
      align-items: center;
      gap: 12px;
      font-size: 15px;
      color: var(--gray-700);
    }

    .safety-list li::before {
      content: '';
      width: 20px;
      height: 20px;
      background: var(--gradient-primary);
      border-radius: 50%;
      flex-shrink: 0;
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .safety-list li::after {
      content: '✓';
      position: relative;
      left: -28px;
      color: var(--white);
      font-size: 11px;
      font-weight: 700;
    }

    /* Creators */
    .creators {
      background: var(--white);
      overflow: hidden;
    }

    .creators-content {
      display: grid;
      grid-template-columns: 1fr;
      gap: 48px;
      align-items: center;
    }

    @media (min-width: 768px) {
      .creators-content {
        grid-template-columns: 1fr 1fr;
      }
    }

    .creators-text .section-heading {
      background: var(--gradient-primary);
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      background-clip: text;
    }

    .creators-text .section-description {
      margin-bottom: 32px;
    }

    .creator-stats {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 24px;
    }

    .stat-item {
      text-align: center;
    }

    .stat-number {
      font-size: 32px;
      font-weight: 800;
      background: var(--gradient-primary);
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      background-clip: text;
    }

    .stat-label {
      font-size: 13px;
      color: var(--gray-500);
      font-weight: 500;
    }

    .creators-visual {
      position: relative;
      background: var(--gray-900);
      border-radius: var(--radius-xl);
      padding: 48px;
      display: flex;
      align-items: center;
      justify-content: center;
      min-height: 350px;
      overflow: hidden;
    }

    .creators-visual::before {
      content: '';
      position: absolute;
      inset: 0;
      background: var(--gradient-primary);
      opacity: 0.15;
    }

    .creators-visual svg {
      width: 140px;
      height: 140px;
      color: var(--white);
      opacity: 0.9;
      position: relative;
      z-index: 1;
    }

    /* Tagline Banner */
    .tagline-banner {
      background: var(--gradient-primary);
      padding: 64px 24px;
      text-align: center;
    }

    .tagline-banner p {
      font-size: clamp(24px, 4vw, 36px);
      font-weight: 700;
      color: var(--white);
      letter-spacing: -0.5px;
    }

    /* News */
    .news {
      background: var(--gray-50);
    }

    .news-header {
      display: flex;
      flex-direction: column;
      gap: 16px;
      margin-bottom: 40px;
    }

    @media (min-width: 768px) {
      .news-header {
        flex-direction: row;
        align-items: flex-end;
        justify-content: space-between;
      }
    }

    .news-header .section-description {
      margin: 0;
    }

    .news-link {
      font-size: 15px;
      font-weight: 600;
      color: var(--purple);
      display: inline-flex;
      align-items: center;
      gap: 6px;
      white-space: nowrap;
    }

    .news-link:hover {
      color: var(--purple-light);
    }

    .news-carousel {
      display: flex;
      gap: 20px;
      overflow-x: auto;
      scroll-snap-type: x mandatory;
      -webkit-overflow-scrolling: touch;
      scrollbar-width: none;
      padding-bottom: 16px;
      margin: 0 -24px;
      padding-left: 24px;
      padding-right: 24px;
    }

    .news-carousel::-webkit-scrollbar {
      display: none;
